# ============================================================================
# Phase C Task C.4: Julia Semantic Analyzer 이식 (FreeLang 구현)
# ============================================================================
# Julia 컴파일러의 시맨틱 분석(Semantic Analysis) 모듈을 FreeLang으로 이식합니다.
#
# 기능:
# - Scope & Symbol Table 관리
# - 변수/함수/상수 선언 추적
# - 타입 검사 (Type Checking)
# - 에러 수집 및 보고
# - 함수 컨텍스트 추적
#
# 목표: Go 시맨틱 분석기와 100% 호환
# 규모: 500줄 (구현 + 테스트)
# ============================================================================

# ============================================================================
# Part 1: Symbol 정의 (변수, 함수, 상수)
# ============================================================================

let KindVariable = "Variable"
let KindFunction = "Function"
let KindConstant = "Constant"
let KindType = "Type"
let KindStruct = "Struct"

record Symbol {
  name: String,              # 심볼 이름
  kind: String,              # 종류 (Variable, Function, Constant 등)
  type_name: String,         # 타입 이름
  mutable: Bool,             # 가변성
  defined_at: (Int, Int),    # 정의된 위치 (line, column)
}

function new_symbol(name: String, kind: String, type_name: String, mutable: Bool, line: Int, column: Int): Symbol =
  Symbol {
    name = name,
    kind = kind,
    type_name = type_name,
    mutable = mutable,
    defined_at = (line, column),
  }

# ============================================================================
# Part 2: Scope 관리
# ============================================================================

record Scope {
  parent: Option[Scope],
  name: String,              # 스코프 이름 (함수명 등)
  symbols: Dict[String, Symbol],
  depth: Int,                # 스코프 깊이
}

function new_scope(name: String, depth: Int): Scope =
  Scope {
    parent = None,
    name = name,
    symbols = dict([]),
    depth = depth,
  }

function define_symbol(scope: Scope, symbol: Symbol): Result[Scope, String] =
  if lookup(scope.symbols, symbol.name).is_some() then
    Err("Symbol '" + symbol.name + "' already defined in this scope")
  else
    Ok(Scope {
      parent = scope.parent,
      name = scope.name,
      symbols = insert(scope.symbols, symbol.name, symbol),
      depth = scope.depth,
    })

function lookup_symbol(scope: Scope, name: String): Option[Symbol] =
  match lookup(scope.symbols, name) {
    Some(sym) -> Some(sym),
    None ->
      match scope.parent {
        Some(parent) -> lookup_symbol(parent, name),
        None -> None,
      },
  }

function lookup_symbol_local(scope: Scope, name: String): Option[Symbol] =
  lookup(scope.symbols, name)

# ============================================================================
# Part 3: ScopeStack 관리 (스택 구조)
# ============================================================================

record ScopeStack {
  scopes: [Scope],
  type_registry: TypeRegistry,
}

function new_scope_stack(registry: TypeRegistry): ScopeStack =
  let global_scope = new_scope("global", 0)
  ScopeStack {
    scopes = [global_scope],
    type_registry = registry,
  }

function push_scope(stack: ScopeStack, name: String): ScopeStack =
  let current = stack.scopes.last()
  let new_scope_obj = new_scope(name, current.depth + 1)
  let new_scope_obj2 = Scope {
    parent = Some(current),
    name = new_scope_obj.name,
    symbols = new_scope_obj.symbols,
    depth = new_scope_obj.depth,
  }
  ScopeStack {
    scopes = stack.scopes.push(new_scope_obj2),
    type_registry = stack.type_registry,
  }

function pop_scope(stack: ScopeStack): ScopeStack =
  if stack.scopes.length > 1 then
    ScopeStack {
      scopes = stack.scopes.slice(0, stack.scopes.length - 1),
      type_registry = stack.type_registry,
    }
  else
    stack

function define_in_scope(stack: ScopeStack, symbol: Symbol): Result[ScopeStack, String] =
  let current = stack.scopes.last()
  match define_symbol(current, symbol) {
    Ok(updated_scope) ->
      let updated_scopes = stack.scopes.slice(0, stack.scopes.length - 1).push(updated_scope)
      Ok(ScopeStack {
        scopes = updated_scopes,
        type_registry = stack.type_registry,
      }),
    Err(e) -> Err(e),
  }

function lookup_in_stack(stack: ScopeStack, name: String): Option[Symbol] =
  let current = stack.scopes.last()
  lookup_symbol(current, name)

# ============================================================================
# Part 4: Semantic Error 정의
# ============================================================================

record SemanticError {
  message: String,
  line: Int,
  column: Int,
}

# ============================================================================
# Phase C Task C.1: Lexer 테스트 (18개 테스트 케이스)
# ============================================================================

# Test 1: 기본 토큰 인식
function test_basic_tokens(): Bool =
  let lex = new_lexer("+ - * /")
  let (lex1, tok1) = next_token(lex)
  let (lex2, tok2) = next_token(lex1)
  let (lex3, tok3) = next_token(lex2)
  let (lex4, tok4) = next_token(lex3)

  tok1.type == TokenPlus &&
  tok2.type == TokenMinus &&
  tok3.type == TokenStar &&
  tok4.type == TokenSlash

# Test 2: 정수 인식
function test_integer_token(): Bool =
  let lex = new_lexer("42")
  let (_, tok) = next_token(lex)
  tok.type == TokenInteger && tok.lexeme == "42"

# Test 3: 부동소수점 인식
function test_float_token(): Bool =
  let lex = new_lexer("3.14")
  let (_, tok) = next_token(lex)
  tok.type == TokenFloat && tok.lexeme == "3.14"

# Test 4: 문자열 인식
function test_string_token(): Bool =
  let lex = new_lexer("\"hello world\"")
  let (_, tok) = next_token(lex)
  tok.type == TokenString && tok.lexeme == "\"hello world\""

# Test 5: 식별자 인식
function test_identifier_token(): Bool =
  let lex = new_lexer("myVariable")
  let (_, tok) = next_token(lex)
  tok.type == TokenIdentifier && tok.lexeme == "myVariable"

# Test 6: 키워드 인식 (if)
function test_keyword_if(): Bool =
  let lex = new_lexer("if")
  let (_, tok) = next_token(lex)
  tok.type == TokenIf && tok.lexeme == "if"

# Test 7: 키워드 인식 (function)
function test_keyword_function(): Bool =
  let lex = new_lexer("function")
  let (_, tok) = next_token(lex)
  tok.type == TokenFunction && tok.lexeme == "function"

# Test 8: 키워드 인식 (return)
function test_keyword_return(): Bool =
  let lex = new_lexer("return")
  let (_, tok) = next_token(lex)
  tok.type == TokenReturn && tok.lexeme == "return"

# Test 9: 심볼 인식
function test_symbol_token(): Bool =
  let lex = new_lexer(":mySymbol")
  let (_, tok) = next_token(lex)
  tok.type == TokenSymbol && tok.lexeme == ":mySymbol"

# Test 10: 복합 연산자
function test_compound_operator(): Bool =
  let lex = new_lexer("+=")
  let (_, tok) = next_token(lex)
  tok.type == TokenPlusAssign && tok.lexeme == "+="

# Test 11: 괄호 인식
function test_parentheses(): Bool =
  let lex = new_lexer("()")
  let (lex1, tok1) = next_token(lex)
  let (_, tok2) = next_token(lex1)
  tok1.type == TokenLeftParen && tok2.type == TokenRightParen

# Test 12: 대괄호 인식
function test_brackets(): Bool =
  let lex = new_lexer("[]")
  let (lex1, tok1) = next_token(lex)
  let (_, tok2) = next_token(lex1)
  tok1.type == TokenLeftBracket && tok2.type == TokenRightBracket

# Test 13: 중괄호 인식
function test_braces(): Bool =
  let lex = new_lexer("{}")
  let (lex1, tok1) = next_token(lex)
  let (_, tok2) = next_token(lex1)
  tok1.type == TokenLeftBrace && tok2.type == TokenRightBrace

# Test 14: 쉼표 및 점 인식
function test_comma_and_dot(): Bool =
  let lex = new_lexer(",.")
  let (lex1, tok1) = next_token(lex)
  let (_, tok2) = next_token(lex1)
  tok1.type == TokenComma && tok2.type == TokenDot

# Test 15: 개행 토큰

